import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:povarspravka/core/calculation/calculation_engine.dart';
import 'package:povarspravka/core/calculation/models/heat_process.dart';
import 'package:povarspravka/core/calculation/models/loss_group.dart';
import 'package:povarspravka/data/repositories/dish_storage_repository.dart';
import 'reaudit_io_support.dart';
void main(){
 TestWidgetsFlutterBinding.ensureInitialized();tearDown(DishStorageRepository.resetForTesting);
 test('I01 stale draft generation must not win',()async{final s=await newStore('a3gen');final r=DishStorageRepository(storageDirectory:s.dir);final a=mkDish(id:'a');await r.saveAll(activeDraft:mkDish(id:'d0'),savedDishes:[a]);await r.saveAll(activeDraft:mkDish(id:'stale'),savedDishes:[a]);await r.saveAll(activeDraft:mkDish(id:'fresh'),savedDishes:[a,mkDish(id:'b')]);DishStorageRepository.resetForTesting();final d=await DishStorageRepository(storageDirectory:s.dir).loadAll();expect(d.activeDraft!.id,'fresh');expect(d.savedDishes.map((x)=>x.id),['a','b']);});
 test('I02 override survives real save load',()async{final s=await newStore('a3rt');final a=mkDish(id:'a').copyWith(process:HeatProcess.boil,ingredients:[mkDish(id:'a').ingredients.single.copyWith(groupOverride:LossGroup.fish,processOverride:HeatProcess.fry)]);await DishStorageRepository(storageDirectory:s.dir).saveAll(activeDraft:a,savedDishes:[a]);DishStorageRepository.resetForTesting();final d=(await DishStorageRepository(storageDirectory:s.dir).loadAll()).activeDraft!;expect(d.ingredients.single.groupOverride,LossGroup.fish);expect(d.ingredients.single.processOverride,HeatProcess.fry);expect(CalculationEngine.calculate(d).cookedFat,CalculationEngine.calculate(a).cookedFat);});
 for(final which in ['main','draft']){test('I03 corrupt $which restores and warns',()async{final s=await newStore('a3bad');final r=DishStorageRepository(storageDirectory:s.dir);final a=mkDish(id:'a');await r.saveAll(activeDraft:mkDish(id:'d0'),savedDishes:[a]);await r.saveAll(activeDraft:mkDish(id:'d1'),savedDishes:[a]);await r.saveAll(activeDraft:mkDish(id:'d2'),savedDishes:[a]);await r.saveAll(activeDraft:mkDish(id:'d3'),savedDishes:[a,mkDish(id:'b')]);await(which=='main'?s.lib:s.draft).writeAsString('{broken',flush:true);DishStorageRepository.resetForTesting();final n=DishStorageRepository(storageDirectory:s.dir);final x=await n.loadAll();expect(x.savedDishes,isNotEmpty);expect(n.recoveryNotice,isNotNull);});}
 test('I04 measured disk commit with and without competing reader',timeout:const Timeout(Duration(minutes:3)),()async{final result=<Map<String,Object?>>[];for(final pause in [-1,0,1,10]){final s=await newStore('a3perf');final r=DishStorageRepository(storageDirectory:s.dir);await r.saveAll(activeDraft:mkDish(id:'d0'),savedDishes:[mkDish(id:'l0')]);var active=true;var reads=0;Future<void> reader()async{while(active){try{await s.lib.readAsBytes();reads++;}on FileSystemException{}if(pause>0)await Future<void>.delayed(Duration(milliseconds:pause));}}final pending=pause>=0?reader():Future<void>.value();final times=<int>[];var failures=0;for(var i=1;i<=20;i++){final sw=Stopwatch()..start();try{await r.saveAll(activeDraft:mkDish(id:'d$i'),savedDishes:[mkDish(id:'l$i')]);}on FileSystemException catch(e){failures++;print('AUDIT3_IO_FAILURE pause=$pause i=$i error=$e');}times.add(sw.elapsedMicroseconds);}active=false;await pending;times.sort();result.add({'pause_ms':pause,'operations':20,'reads':reads,'failures':failures,'min_us':times.first,'median_us':times[times.length~/2],'max_us':times.last,'sum_us':times.reduce((a,b)=>a+b)});print('AUDIT3_IO_PHASE ${jsonEncode(result.last)}');expect(failures,0);DishStorageRepository.resetForTesting();expect((await DishStorageRepository(storageDirectory:s.dir).loadAll()).savedDishes.single.id,'l20');}final p=Platform.environment['AUDIT3_OUT'];if(p!=null)await File('$p/io_timings.json').writeAsString(jsonEncode(result));print('AUDIT3_IO_TIMINGS ${jsonEncode(result)}');});
}
